#version 300 es
precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_intensity;
out vec4 color;
float hash21(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float noise(vec2 p){
  vec2 i=floor(p),f=fract(p); f=f*f*(3.0-2.0*f);
  return mix(mix(hash21(i),hash21(i+vec2(1,0)),f.x),
             mix(hash21(i+vec2(0,1)),hash21(i+vec2(1,1)),f.x),f.y);
}
float fbm(vec2 p){
  float value=0.0,amplitude=0.5;
  mat2 rotation=mat2(0.8,-0.6,0.6,0.8);
  for(int i=0;i<5;i++){value+=amplitude*noise(p);p=rotation*p*2.03+vec2(4.3,1.7);amplitude*=0.5;}
  return value;
}
void main(){
  vec2 uv=gl_FragCoord.xy/u_resolution;
  vec2 p=(uv-0.5)*vec2(u_resolution.x/u_resolution.y,1.0)*3.0;
  float speed=0.25;
  float t=u_time*speed;
  vec2 warp=vec2(fbm(p+vec2(t,0)),fbm(p+vec2(4.1,-t)));
  float field=fbm(p+warp*3.0);
  float strands=pow(0.5+0.5*sin(field*24.0-t*2.0),5.0);
  vec3 coral=mix(vec3(0.025,0.045,0.12),vec3(1.0,0.32,0.22),field);
  coral+=strands*vec3(0.18,0.65,0.8)*u_intensity;
  coral*=1.0-0.35*dot(uv-0.5,uv-0.5);
  color=vec4(coral,1.0);
}

#version 300 es
precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
out vec4 color;
void main(){vec2 uv=gl_FragCoord.xy/u_resolution; color=vec4(uv,0.25,1.0);}

#version 300 es
precision highp float;
uniform vec2 u_resolution;
uniform sampler2D u_input;
out vec4 color;
void main(){vec2 uv=gl_FragCoord.xy/u_resolution; color=texture(u_input,uv);}

#version 300 es
void main(){ vec2 p=vec2((gl_VertexID<<1)&2,gl_VertexID&2); gl_Position=vec4(p*2.0-1.0,0.0,1.0); }
